export function highlightMentions(body: string): string {
  const codeRanges: Array<[number, number]> = [];
  for (const match of body.matchAll(/```[\s\S]*?```/g)) {
    codeRanges.push([match.index!, match.index! + match[0].length]);
  }
  for (const match of body.matchAll(/`[^`]*`/g)) {
    codeRanges.push([match.index!, match.index! + match[0].length]);
  }

  const isInCode = (pos: number): boolean =>
    codeRanges.some(([start, end]) => pos >= start && pos < end);

  let result = body;
  let offset = 0;

  for (const match of body.matchAll(MENTION_PATTERN)) {
    if (isInCode(match.index! + match[1].length)) continue;
    const replacement = `${match[1]}<span class="mention">@${match[2]}</span>`;
    const pos = match.index! + offset;
    result = result.slice(0, pos) + replacement + result.slice(pos + match[0].length);
    offset += replacement.length - match[0].length;
  }

  return result;
}

